    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion at the end
    if len(s_in) < len(s_out):
        # Check if we're inserting at the end
        if s_in == s_out[:len(s_in)]:
            return ("", s_out[len(s_in):], len(s_in))
    elif len(s_in) > len(s_out):
        # Check if we're deleting at the end
        if s_out == s_in[:len(s_out)]:
            return (s_in[len(s_out):], "", len(s_out))

    # Check for substitution or replacement in middle
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if it's a simple replacement
            # Look for the substring that needs to change
            # For simplicity, let's assume it's a single character replacement
            return (s_in[i], s_out[i], i)

    # If we get here, one string is prefix of the other
    # Check if it's an insertion or deletion
    if len(s_in) < len(s_out):
        return ("", s_out[len(s_in):], len(s_in))
    elif len(s_in) > len(s_out):
        return (s_in[len(s_out):], "", len(s_out))
